RidgeTraceBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "RidgeTraceBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "GCEstimjmv",
                name = "RidgeTrace",
                version = c(1,0,0),
                options = options,
                results = RidgeTraceResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'auto')
        }))

#' Ridge Trace
#'
#' 
#' @param run .
#' @param data .
#' @param dep .
#' @param covs .
#' @param factors .
#' @param intercept .
#' @param standardize .
#' @param penalizeIntercept .
#' @param customGrid .
#' @param lambdaMin .
#' @param lambdaMax .
#' @param lambdaN .
#' @param lambdaValues .
#' @param cv .
#' @param cvNfolds .
#' @param seed .
#' @param errorMeasure .
#' @param selection .
#' @param manualIndex .
#' @param showLambdaTable .
#' @param tableRows .
#' @param axisScale .
#' @param showIntercept .
#' @param extrema .
#' @param facet .
#' @param displayTerms .
#' @param seBars .
#' @param foldMean .
#' @param plotPaths .
#' @param plotCV .
#' @param plotSample .
#' @param plotRanges .
#' @param plotSensitivity .
#' @param plotFolds .
#' @param plotStability .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$fitCache} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$text} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$modelSummary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$coefficients} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$coefficientRanges} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$lambdaResults} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plotPaths} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plotCV} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plotSample} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plotRanges} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plotSensitivity} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plotFolds} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plotStability} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$fitCache$asDF}
#'
#' \code{as.data.frame(results$fitCache)}
#'
#' @export
RidgeTrace <- function(
    run = FALSE,
    data,
    dep,
    covs,
    factors,
    intercept = TRUE,
    standardize = TRUE,
    penalizeIntercept = TRUE,
    customGrid = FALSE,
    lambdaMin = 0.001,
    lambdaMax = 1000,
    lambdaN = 100,
    lambdaValues = "0.001, 0.01, 0.1, 1, 10, 100, 1000",
    cv = TRUE,
    cvNfolds = 5,
    seed = 230676,
    errorMeasure = "RMSE",
    selection = "min",
    manualIndex = 1,
    showLambdaTable = FALSE,
    tableRows = 100,
    axisScale = "log",
    showIntercept = TRUE,
    extrema = FALSE,
    facet = FALSE,
    displayTerms = "",
    seBars = TRUE,
    foldMean = TRUE,
    plotPaths = TRUE,
    plotCV = TRUE,
    plotSample = "auto",
    plotRanges = FALSE,
    plotSensitivity = FALSE,
    plotFolds = FALSE,
    plotStability = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("RidgeTrace requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dep)) dep <- jmvcore::resolveQuo(jmvcore::enquo(dep))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if ( ! missing(factors)) factors <- jmvcore::resolveQuo(jmvcore::enquo(factors))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dep), dep, NULL),
            `if`( ! missing(covs), covs, NULL),
            `if`( ! missing(factors), factors, NULL))


    options <- RidgeTraceOptions$new(
        run = run,
        dep = dep,
        covs = covs,
        factors = factors,
        intercept = intercept,
        standardize = standardize,
        penalizeIntercept = penalizeIntercept,
        customGrid = customGrid,
        lambdaMin = lambdaMin,
        lambdaMax = lambdaMax,
        lambdaN = lambdaN,
        lambdaValues = lambdaValues,
        cv = cv,
        cvNfolds = cvNfolds,
        seed = seed,
        errorMeasure = errorMeasure,
        selection = selection,
        manualIndex = manualIndex,
        showLambdaTable = showLambdaTable,
        tableRows = tableRows,
        axisScale = axisScale,
        showIntercept = showIntercept,
        extrema = extrema,
        facet = facet,
        displayTerms = displayTerms,
        seBars = seBars,
        foldMean = foldMean,
        plotPaths = plotPaths,
        plotCV = plotCV,
        plotSample = plotSample,
        plotRanges = plotRanges,
        plotSensitivity = plotSensitivity,
        plotFolds = plotFolds,
        plotStability = plotStability)

    analysis <- RidgeTraceClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

